@pragma('vm:entry-point')
String sortPasswordViolationsBySeverity(List<String> violations) {
  if (violations.isEmpty) return '';
  int severityRank(String msg) {
    if (msg.startsWith('[CRITICAL]')) return 0;
    if (msg.startsWith('[WARNING]')) return 1;
    if (msg.startsWith('[INFO]')) return 2;
    return 3;
  }
  final sorted = List<String>.from(violations);
  sorted.sort((a, b) {
    final rankA = severityRank(a);
    final rankB = severityRank(b);
    if (rankA != rankB) return rankA.compareTo(rankB);
    return a.compareTo(b);
  });
  return sorted.join('|');
}

@pragma('vm:entry-point')
void main() {
  assert(sortPasswordViolationsBySeverity([]) == '');
  assert(sortPasswordViolationsBySeverity(['[INFO] too short', '[CRITICAL] no uppercase', '[WARNING] no digit', '[CRITICAL] no symbol']) == '[CRITICAL] no symbol|[CRITICAL] no uppercase|[WARNING] no digit|[INFO] too short');
  assert(sortPasswordViolationsBySeverity(['[WARNING] weak pattern', '[INFO] consider longer']) == '[WARNING] weak pattern|[INFO] consider longer');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = sortPasswordViolationsBySeverity;

  expect(candidate([]), '');
  expect(candidate(['[INFO] too short']), '[INFO] too short');
  expect(candidate(['[CRITICAL] no uppercase', '[CRITICAL] no symbol']), '[CRITICAL] no symbol|[CRITICAL] no uppercase');
  expect(candidate(['[INFO] too short', '[CRITICAL] no uppercase', '[WARNING] no digit', '[CRITICAL] no symbol']), '[CRITICAL] no symbol|[CRITICAL] no uppercase|[WARNING] no digit|[INFO] too short');
  expect(candidate(['[WARNING] no digit', '[WARNING] all lowercase', '[INFO] short']), '[WARNING] all lowercase|[WARNING] no digit|[INFO] short');
  expect(candidate(['[INFO] b', '[INFO] a', '[CRITICAL] z', '[WARNING] m']), '[CRITICAL] z|[WARNING] m|[INFO] a|[INFO] b');
  expect(candidate(['[UNKNOWN] custom rule', '[CRITICAL] no uppercase']), '[CRITICAL] no uppercase|[UNKNOWN] custom rule');
  expect(candidate(['[WARNING] only one']), '[WARNING] only one');
  expect(candidate(['[INFO] c', '[CRITICAL] a', '[INFO] a', '[WARNING] b']), '[CRITICAL] a|[WARNING] b|[INFO] a|[INFO] c');
}

