@pragma('vm:entry-point')
List<int> sortBarcodeDigitsByBitPositionSum(List<int> digits) {
  const patterns = <int, String>{
    0: '0001101',
    1: '0011001',
    2: '0010011',
    3: '0111101',
    4: '0100011',
    5: '0110001',
    6: '0101111',
    7: '0111011',
    8: '0110111',
    9: '0001011',
  };

  int sumOfPositions(String s) {
    int sum = 0;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '1') sum += i;
    }
    return sum;
  }

  int binaryValue(String s) {
    return int.parse(s, radix: 2);
  }

  int compareDigits(int a, int b) {
    String pa = patterns[a]!;
    String pb = patterns[b]!;
    int sumA = sumOfPositions(pa);
    int sumB = sumOfPositions(pb);
    if (sumA != sumB) return sumA.compareTo(sumB);
    int binA = binaryValue(pa);
    int binB = binaryValue(pb);
    if (binA != binB) return binA.compareTo(binB);
    return a.compareTo(b);
  }

  List<int> sorted = List<int>.of(digits);
  sorted.sort(compareDigits);
  return sorted;
}

@pragma('vm:entry-point')
void main() {
  assert(sortBarcodeDigitsByBitPositionSum([3, 0, 1, 2]).toString() == '[1, 0, 2, 3]');
  assert(sortBarcodeDigitsByBitPositionSum([9, 8, 7, 6, 5, 4, 3, 2, 1, 0]).toString() == '[5, 1, 4, 0, 2, 9, 3, 7, 8, 6]');
  assert(sortBarcodeDigitsByBitPositionSum([]).toString() == '[]');
  print('All tests passed!');
}

tests:
