  final candidate = sortBarcodeDigitsByBitPositionSum;

  expect(candidate([]), []);
  expect(candidate([5]), [5]);
  expect(candidate([9, 3, 1, 7]), [1, 9, 3, 7]);
  expect(candidate([2, 2, 1]), [1, 2, 2]);
