  expect(candidate([4, 0, 4, 0, 4]), [4, 4, 4, 0, 0]);
  expect(candidate([5, 5, 5, 1, 0, 2, 9, 3, 7, 8, 6, 5]), [5, 5, 5, 5, 1, 0, 2, 9, 3, 7, 8, 6]);
  expect(candidate([1, 0, 2, 3, 4, 5, 6, 7, 8, 9]), [5, 1, 4, 0, 2, 9, 3, 7, 8, 6]);
