@pragma('vm:entry-point')
Map<String, int> rankShelfCodes(List<String> codes) {
  final sorted = List<String>.from(codes);
  final re = RegExp(r'^([A-Z]+)(\d+)(?:\.(\d+))?$');
  sorted.sort((a, b) {
    final ma = re.firstMatch(a)!, mb = re.firstMatch(b)!;
    final ca = ma.group(1)!.compareTo(mb.group(1)!);
    if (ca != 0) return ca;
    final na = int.parse(ma.group(2)!), nb = int.parse(mb.group(2)!);
    if (na != nb) return na.compareTo(nb);
    final da = ma.group(3) ?? '', db = mb.group(3) ?? '';
    final m = da.length > db.length ? da.length : db.length;
    final va = da.isEmpty ? 0 : int.parse(da.padRight(m, '0'));
    final vb = db.isEmpty ? 0 : int.parse(db.padRight(m, '0'));
    if (va != vb) return va.compareTo(vb);
    return a.compareTo(b);
  });
  final ranks = <String, int>{};
  for (var k = 0; k < sorted.length; k++) ranks[sorted[k]] = k + 1;
  return ranks;
}

@pragma('vm:entry-point')
void main() {
  assert(rankShelfCodes([]).isEmpty);
  assert(rankShelfCodes(['QA76']).toString() == '{QA76: 1}');
  assert(rankShelfCodes(['B2', 'A1']).length == 2);
  print('All tests passed!');
}

tests:
