  final candidate = orderTrafficPhases;

  expect(candidate([]), '');
  expect(candidate(['R10-Y5-G30']), 'R10-Y5-G30');
  expect(candidate(['R30-Y5-G25', 'R20-Y3-G37', 'R10-Y2-G8', 'R15-Y5-G20', 'R10-Y5-G15']), 'R20-Y3-G37, R10-Y5-G15, R15-Y5-G20, R30-Y5-G25, R10-Y2-G8');
  expect(candidate(['R20-Y10-G20', 'R15-Y15-G20']), 'R15-Y15-G20, R20-Y10-G20');
  expect(candidate(['R10-Y5-G15', 'R20-Y10-G30', 'R5-Y2-G7']), 'R5-Y2-G7, R10-Y5-G15, R20-Y10-G30');
