@pragma('vm:entry-point')
bool canFormExactCoalition(List<int> partySeats, int requiredCoalitionSize, int targetSeats) {
  bool backtrack(int index, int remainingSize, int remainingTarget) {
    if (remainingSize == 0 && remainingTarget == 0) return true;
    if (remainingSize <= 0 || index >= partySeats.length) return false;
    if (remainingTarget < 0) return false;

    bool include = backtrack(index + 2, remainingSize - 1, remainingTarget - partySeats[index]);
    if (include) return true;

    return backtrack(index + 1, remainingSize, remainingTarget);
  }

  return backtrack(0, requiredCoalitionSize, targetSeats);
}

