@pragma('vm:entry-point')
int countWifiBinPartitions(List<int> signals, int maxTolerance) {
  if (signals.isEmpty) return 0;

  int solve(int L, int R) {
    if (L == R) return 1;

    int minSig = signals[L];
    int maxSig = signals[L];
    for (int i = L + 1; i <= R; i++) {
      if (signals[i] < minSig) minSig = signals[i];
      if (signals[i] > maxSig) maxSig = signals[i];
    }

    int mid = (L + R) ~/ 2;
    int splitWays = solve(L, mid) * solve(mid + 1, R);

    if (maxSig - minSig <= maxTolerance) {
      return 1 + splitWays;
    } else {
      return splitWays;
    }
  }

  return solve(0, signals.length - 1);
}

@pragma('vm:entry-point')
void main() {
  assert(countWifiBinPartitions([], 2) == 0);
  assert(countWifiBinPartitions([-50, -50], 0) == 2);
  print('All tests passed!');
}

