Set<int> leadCardsFromTrumpSortedDeck(List<int> deck, int trumpSuit, bool acesHigh, int chunkSize) {
  final Set<int> result = <int>{};
  if (chunkSize <= 0 || trumpSuit < 0 || trumpSuit > 3) return result;

  final List<int> cards = <int>[];
  final Set<int> seen = <int>{};
  for (final int code in deck) {
    if (code >= 0 && code < 52 && !seen.contains(code)) {
      seen.add(code);
      cards.add(code);
    }
  }

  int suitOrder(int suit) {
    return suit == trumpSuit ? 0 : (suit < trumpSuit ? suit + 1 : suit);
  }

  int rankPower(int rank) => acesHigh && rank == 0 ? 13 : rank;

  cards.sort((int a, int b) {
    final int suitCompare = suitOrder(a ~/ 13).compareTo(suitOrder(b ~/ 13));
    if (suitCompare != 0) return suitCompare;
    final int rankCompare = rankPower(b % 13).compareTo(rankPower(a % 13));
    if (rankCompare != 0) return rankCompare;
    return a.compareTo(b);
  });

  for (int i = 0; i < cards.length; i += chunkSize) {
    result.add(cards[i]);
  }
  return result;
}

