@pragma('vm:entry-point')
Set<int> decodeTideHeights(String encoded) {
  final result = <int>{};
  int i = 0;
  while (i < encoded.length) {
    int colon = encoded.indexOf(':', i);
    if (colon == -1) break;
    String runStr = encoded.substring(i, colon);
    if (runStr.isEmpty) break;
    int runLength;
    try {
      runLength = int.parse(runStr, radix: 36);
    } catch (_) {
      break;
    }
    if (runLength <= 0) {
      i = colon + 1;
      continue;
    }
    if (colon + 2 >= encoded.length) break;
    String heightChar = encoded[colon + 1];
    String checksumChar = encoded[colon + 2];
    int shiftedHeight = heightChar.codeUnitAt(0) - '0'.codeUnitAt(0);
    int shift = runLength % 10;
    int originalHeight = (shiftedHeight - shift + 10) % 10;
    int expectedChecksum = (runLength + originalHeight) % 10;
    int actualChecksum = checksumChar.codeUnitAt(0) - 'A'.codeUnitAt(0);
    if (actualChecksum == expectedChecksum) {
      result.add(originalHeight);
    }
    i = colon + 3;
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeTideHeights("1:1B").length == 1);
  assert(decodeTideHeights("1:1B").contains(0));
