  assert(computeWifiSignalMedianBin([], []) == 0.0);
  assert(computeWifiSignalMedianBin([1], [-50]) == 4.0);
  assert(computeWifiSignalMedianBin([1, 2], [-50, -55]) == 3.5);
  print('All tests passed!');
}

