Map<String, int> decodePacketStream(String encoded) {
  int totalPackets = 0;
  int checksum = 0;
  int maxSize = 0;
  Set<int> uniqueSizes = {};

  if (encoded.isEmpty) {
    return {
      'totalPackets': 0,
      'checksum': 0,
      'maxSize': 0,
      'uniqueSizes': 0
    };
  }

  List<String> runs = encoded.split(',');
  for (String run in runs) {
    List<String> parts = run.split(':');
    if (parts.length != 2) continue;
    int count = int.tryParse(parts[0]) ?? 0;
    int size = int.tryParse(parts[1]) ?? 0;
    if (count <= 0) continue;
    totalPackets += count;
    checksum = (checksum + size * count) % 256;
    if (size > maxSize) maxSize = size;
    uniqueSizes.add(size);
  }

  return {
    'totalPackets': totalPackets,
    'checksum': checksum,
    'maxSize': maxSize,
    'uniqueSizes': uniqueSizes.length
  };
}

@pragma('vm:entry-point')
void main() {
  assert(decodePacketStream("3:100,2:200,1:150")["checksum"] == 82);
  assert(decodePacketStream("1:500")["totalPackets"] == 1);
  assert(decodePacketStream("")["maxSize"] == 0);
