@pragma('vm:entry-point')
String findStableWindow(List<int> readings, int threshold) {
  if (readings.isEmpty) return "-1,-1";
  int n = readings.length;
  List<int> maxDeque = [];
  List<int> minDeque = [];
  int left = 0;
  int bestStart = 0, bestEnd = 0;
  for (int right = 0; right < n; right++) {
    while (maxDeque.isNotEmpty && readings[maxDeque.last] <= readings[right]) {
      maxDeque.removeLast();
    }
    maxDeque.add(right);
    while (minDeque.isNotEmpty && readings[minDeque.last] >= readings[right]) {
      minDeque.removeLast();
    }
    minDeque.add(right);
    while (readings[maxDeque.first] - readings[minDeque.first] > threshold) {
      if (maxDeque.first == left) maxDeque.removeAt(0);
      if (minDeque.first == left) minDeque.removeAt(0);
      left++;
    }
    if (right - left > bestEnd - bestStart) {
      bestStart = left;
      bestEnd = right;
    }
  }
  return "$bestStart,$bestEnd";
}

@pragma('vm:entry-point')
void main() {
  assert(findStableWindow([], 5) == "-1,-1");
  assert(findStableWindow([10], 0) == "0,0");
  assert(findStableWindow([1, 2, 3, 4, 5], 1) == "0,1");
