@pragma('vm:entry-point')
Map<String, int> parseShippingManifest(String manifest) {
  final result = <String, int>{};
  var state = 0; // 0 = before manifest, 1 = inside manifest, 2 = after END
  for (final rawLine in manifest.split('\n')) {
    final line = rawLine.trim();
    if (state == 0) {
      if (line == 'MANIFEST') state = 1;
    } else if (state == 1) {
      if (line == 'END') {
        state = 2;
      } else if (line.isNotEmpty && !line.startsWith('#')) {
        final parts = line.split(RegExp(r'\s+'));
        if (parts.length == 4 && parts[0] == 'CONTAINER') {
          final weight = int.tryParse(parts[2]);
          if (weight != null) {
            final dest = parts[3];
            result[dest] = (result[dest] ?? 0) + weight;
          }
        }
      }
    }
    // state 2 ignores everything
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(parseShippingManifest('MANIFEST\nEND').isEmpty);
  assert(parseShippingManifest('MANIFEST\nCONTAINER C001 1000 NYC\nEND')['NYC'] == 1000);
  assert(parseShippingManifest('MANIFEST\nCONTAINER C001 1000 NYC\nCONTAINER C002 2000 NYC\nEND')['NYC'] == 3000);
  print('All tests passed!');
}

