@pragma('vm:entry-point')
bool checkHashBucketUniformity(int bucketCount, List<String> operations) {
  if (bucketCount <= 0) return false;
  final buckets = List<int>.filled(bucketCount, 0);
  final keyToBucket = <String, int>{};
  final undoStack = <List<Object>>[];

  int hash(String key) {
    var sum = 0;
    for (var i = 0; i < key.length; i++) {
      sum += key.codeUnitAt(i);
    }
    return sum % bucketCount;
  }

  for (final op in operations) {
    final parts = op.split(' ');
    if (parts[0] == 'insert') {
      final key = parts[1];
      if (keyToBucket.containsKey(key)) continue;
      final bucket = hash(key);
      buckets[bucket]++;
      keyToBucket[key] = bucket;
      undoStack.add([key, true]);
    } else if (parts[0] == 'delete') {
      final key = parts[1];
      if (!keyToBucket.containsKey(key)) continue;
      final bucket = keyToBucket[key]!;
      buckets[bucket]--;
      keyToBucket.remove(key);
      undoStack.add([key, false]);
    } else if (parts[0] == 'undo') {
      if (undoStack.isEmpty) continue;
      final last = undoStack.removeLast();
      final key = last[0] as String;
      final isInsert = last[1] as bool;
      if (isInsert) {
        final bucket = keyToBucket[key]!;
        buckets[bucket]--;
        keyToBucket.remove(key);
      } else {
        final bucket = hash(key);
        buckets[bucket]++;
        keyToBucket[key] = bucket;
      }
    }
  }

  final firstCount = buckets[0];
  for (final count in buckets) {
    if (count != firstCount) return false;
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(checkHashBucketUniformity(3, []) == true);
  assert(checkHashBucketUniformity(3, ["insert a", "insert b", "insert c"]) == true);
  assert(checkHashBucketUniformity(2, ["insert a"]) == false);
  print('All tests passed!');
}

