@pragma('vm:entry-point')
bool isTidalSumSafe(List<int> lowTides, List<int> highTides, int k, int s) {
  if (lowTides.isEmpty || highTides.isEmpty || k <= 0) return false;
  int totalPairs = lowTides.length * highTides.length;
  if (k > totalPairs) return false;

  int countLE(int target) {
    int count = 0;
    int j = highTides.length - 1;
    for (int i = 0; i < lowTides.length; i++) {
      while (j >= 0 && lowTides[i] + highTides[j] > target) {
        j--;
      }
      count += j + 1;
    }
    return count;
  }

  int left = lowTides.first + highTides.first;
  int right = lowTides.last + highTides.last;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (countLE(mid) >= k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left <= s;
}

@pragma('vm:entry-point')
void main() {
  assert(isTidalSumSafe([1, 3], [2, 4], 2, 5) == true);
  assert(isTidalSumSafe([1, 2, 3], [2, 4, 6], 5, 5) == false);
  assert(isTidalSumSafe([], [1, 2], 1, 5) == false);
  print('All tests passed!');
}

