Set<int> collectItemIdsFromNestedSlots(Map<String, dynamic> inventory) {
  Set<int> result = <int>{};
  _traverse(inventory, result);
  return result;
}

void _traverse(Map<String, dynamic> node, Set<int> collector) {
  if (node.containsKey('itemId') && node['itemId'] is int) {
    collector.add(node['itemId'] as int);
  }
  if (node.containsKey('slots') && node['slots'] is List) {
    for (var slot in node['slots'] as List) {
      if (slot is Map<String, dynamic>) {
        _traverse(slot, collector);
      }
    }
  }
}

