@pragma('vm:entry-point')
int smallestCoprimeBucketSize(List<int> groupCounts) {
  int total = 0;
  for (int c in groupCounts) {
    if (c > 0) total += c;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }

  int candidate = total < 2 ? 2 : total;
  const int maxSearch = 100000;
  while (candidate <= maxSearch) {
    if (isPrime(candidate)) {
      bool allCoprime = true;
      for (int c in groupCounts) {
        if (c > 0 && gcd(candidate, c) != 1) {
          allCoprime = false;
          break;
        }
      }
      if (allCoprime) {
        return candidate;
