Map<String, int> barcodeDigitTransformFrequencies(List<int> digits) {
  final counts = <String, int>{};
  for (var i = 0; i < digits.length; i++) {
    int digit = digits[i];
    int transformed;
    if (i % 2 == 0) {
      transformed = digit * 2;
      if (transformed > 9) {
        transformed -= 9;
      }
    } else {
      transformed = digit;
    }
    counts[transformed.toString()] = (counts[transformed.toString()] ?? 0) + 1;
  }
  return counts;
}

