List<String> nearestTideReadings(List<int> readings, int qx, int qy, int k) {
  if (k <= 0 || readings.isEmpty) return [];
  var triples = <List<int>>[];
  for (int i = 0; i < readings.length; i += 3) {
    int x = readings[i];
    int y = readings[i + 1];
    int h = readings[i + 2];
    int d = (x - qx).abs() + (y - qy).abs();
    triples.add([d, h, i ~/ 3]);
  }
  triples.sort((a, b) {
    int cmp = a[0].compareTo(b[0]);
    if (cmp != 0) return cmp;
    return a[2].compareTo(b[2]);
  });
  var result = <String>[];
  for (int i = 0; i < triples.length && i < k; i++) {
    result.add('distance: ${triples[i][0]}, height: ${triples[i][1]}');
  }
  return result;
}

