double qrCodeDarkModuleRatio(List<int> modules) {
  if (modules.isEmpty) return 0.0;
  if (modules.length == 1) return modules[0].toDouble();
  final mid = modules.length ~/ 2;
  final left = qrCodeDarkModuleRatio(modules.sublist(0, mid));
  final right = qrCodeDarkModuleRatio(modules.sublist(mid));
  return (left * mid + right * (modules.length - mid)) / modules.length;
}

@pragma('vm:entry-point')
