List<int> tallyDrySoilProbes(List<int> gridRows, int probeMask) {
  final counts = <int>[];
  for (var row in gridRows) {
    var masked = row & probeMask;
    var pop = 0;
    while (masked != 0) {
      masked &= masked - 1;
      pop++;
    }
    counts.add(pop);
  }
  return counts;
}

