@pragma('vm:entry-point')
double qrTimingRowMatchRatio(int rowByte) {
  const int ideal = 0x55; // alternating dark/light, starts with dark
  final int diff = (rowByte & 0xFF) ^ ideal;
  int mismatches = 0;
  int mask = diff;
  while (mask != 0) {
    mismatches++;
    mask &= mask - 1;
  }
  return (8 - mismatches) / 8.0;
}

@pragma('vm:entry-point')
void main() {
  assert(qrTimingRowMatchRatio(0x55) == 1.0);
  assert(qrTimingRowMatchRatio(0xAA) == 0.0);
