@pragma('vm:entry-point')
List<String> sortQrRowsByDarknessThenTransitions(List<String> rows) {
  int ones(String s) { var c = 0; for (var i = 0; i < s.length; i++) if (s[i] == '1') c++; return c; }
  int trans(String s) { var c = 0; for (var i = 0; i < s.length - 1; i++) if (s[i] != s[i+1]) c++; return c; }
  final r = List<String>.from(rows);
  r.sort((a, b) {
    final d = ones(b) - ones(a);
    if (d != 0) return d;
    final t = trans(a) - trans(b);
    if (t != 0) return t;
    return a.compareTo(b);
  });
  return r;
}

