void main() {
  assert(straightFlushGapsBySuit([]).isEmpty);
  assert(straightFlushGapsBySuit(["AH", "2H", "3H", "4H", "5H"]).toString() == "{H: 0}");
  assert(straightFlushGapsBySuit(["AH", "KH"]).toString() == "{H: 0}");
