Set<int> findSafeSquareWindows(List<int> occupied, int k) {
  Set<int> result = {};
  int last = 0;
  for (int pos in occupied) {
    int gapStart = last + 1;
    int gapEnd = pos - 1;
    for (int s = gapStart; s <= gapEnd - k + 1; s++) {
      result.add(s);
    }
    last = pos;
  }
  int gapStart = last + 1;
  for (int s = gapStart; s <= 64 - k + 1; s++) {
    if (s >= 1) result.add(s);
  }
  return result;
}

