void main() {
  assert(isValidCardTableLayout([], 10, 10) == true);
  assert(isValidCardTableLayout([[0, 0, 0], [1, 0, 0]], 10, 10) == false);
  assert(isValidCardTableLayout([[0, 0, 0], [2, 0, 0]], 10, 10) == true);
  print('All tests passed!');
}

