int recursivePixelBrightness(List<int> pixels) {
  if (pixels.isEmpty) return -1;
  if (pixels.length == 1) return pixels[0];
  int mid = pixels.length ~/ 2;
  int leftMax = recursivePixelBrightness(pixels.sublist(0, mid));
  int rightMax = recursivePixelBrightness(pixels.sublist(mid));
  return leftMax > rightMax ? leftMax : rightMax;
}

