Map<String, int> analyzeBatteryCycles(List<int> readings) {
  int micro = 0;
  int light = 0;
  int moderate = 0;
  int heavy = 0;
  int stressScore = 0;

  for (int i = 1; i < readings.length; i++) {
    int drop = readings[i - 1] - readings[i];
    if (drop > 0) {
      if (drop <= 5) {
        micro++;
        stressScore += 1;
      } else if (drop <= 15) {
        light++;
        stressScore += 2;
      } else if (drop <= 40) {
        moderate++;
        stressScore += 4;
      } else {
        heavy++;
        stressScore += 8;
      }
    }
  }

  int totalCycles = micro + light + moderate + heavy;
  return {
    'micro': micro,
    'light': light,
    'moderate': moderate,
    'heavy': heavy,
    'total_cycles': totalCycles,
    'stress_score': stressScore,
  };
}

