@pragma('vm:entry-point')
Set<int> findPartialBeamColumns(List<String> rows, int minLit) {
  if (rows.isEmpty) return {};
  int width = rows[0].length;
  if (width == 0) return {};

  int orMask = 0;
  int andMask = (1 << width) - 1;

  List<int> counts = List.filled(width, 0);

  for (String row in rows) {
    int mask = 0;
    for (int j = 0; j < width && j < row.length; j++) {
      if (row[j] != ' ' && row[j] != '.') {
        mask |= (1 << j);
        counts[j]++;
      }
    }
    orMask |= mask;
    andMask &= mask;
  }

  int partial = orMask & ~andMask;

  Set<int> result = {};
  for (int j = 0; j < width; j++) {
    if ((partial & (1 << j)) != 0 && counts[j] >= minLit) {
      result.add(j);
    }
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(findPartialBeamColumns(['#.#', '.#.', '#.#'], 2).toString() == '{0, 2}');
  assert(findPartialBeamColumns(['###', '###'], 1).isEmpty);
