Set<int> topContestedCandidates(List<Map<String, int>> tallies, int topK) {
  Map<int, int> totalVotes = {};
  Map<int, Set<int>> districts = {};
  for (var t in tallies) {
    int c = t['candidate']!;
    int v = t['votes']!;
    int d = t['district']!;
    totalVotes[c] = (totalVotes[c] ?? 0) + v;
    districts.putIfAbsent(c, () => <int>{}).add(d);
  }
  List<int> candidates = totalVotes.keys.toList();
  candidates.sort((a, b) {
    int voteCompare = totalVotes[b]!.compareTo(totalVotes[a]!);
    if (voteCompare != 0) return voteCompare;
    int distCompare = districts[b]!.length.compareTo(districts[a]!.length);
    if (distCompare != 0) return distCompare;
    return a.compareTo(b);
  });
  return candidates.take(topK).toSet();
}

@pragma('vm:entry-point')
void main() {
  assert(topContestedCandidates([{'candidate': 1, 'votes': 100, 'district': 1}, {'candidate': 2, 'votes': 200, 'district': 1}], 1).length == 1);
  assert(topContestedCandidates([], 5).isEmpty);
  assert(topContestedCandidates([{'candidate': 3, 'votes': 50, 'district': 1}], 10).contains(3));
