double calculateAverageRestockGap(List<int> restockDays, int periodStart, int periodEnd) {
  List<int> filtered = [];
  for (int day in restockDays) {
    if (day >= periodStart && day <= periodEnd) {
      filtered.add(day);
    }
  }
  if (filtered.length < 2) return 0.0;
  filtered.sort();
  int totalGap = 0;
  for (int i = 1; i < filtered.length; i++) {
    totalGap += filtered[i] - filtered[i - 1];
  }
  return totalGap / (filtered.length - 1);
}

