List<int> significantRecurringTideBands(List<int> readings) {
  Map<int, int> freq = {};
  for (int r in readings) {
    freq[r] = (freq[r] ?? 0) + 1;
  }
  Set<int> recurring = {};
  for (int key in freq.keys) {
    if (freq[key]! >= 2) {
      recurring.add(key);
    }
  }
  Map<int, Set<int>> bands = {};
  for (int r in recurring) {
    int band = r ~/ 20;
    bands.putIfAbsent(band, () => <int>{});
    bands[band]!.add(r);
  }
  List<int> result = [];
  for (int band in bands.keys) {
    if (bands[band]!.length >= 2) {
      result.add(band);
    }
  }
  result.sort();
  return result;
}

