bool isBatteryCycleBalanced(String log) {
  int netCharge = 0;
  for (String token in log.split(',')) {
    String t = token.trim();
    if (t.isEmpty) continue;
    int amount = int.parse(t.substring(1));
    netCharge += t.startsWith('C') ? amount : -amount;
