List<int> simulateCardMelding(List<int> cards) {
  List<int> discard = [];
  bool nextIsDoubled = false;

  for (int card in cards) {
    int val = card;

    if (nextIsDoubled) {
      val = val * 2;
      if (val > 13) {
        val = 13;
      }
      nextIsDoubled = false;
    }

    if (discard.isNotEmpty && discard.last == val) {
      discard.removeLast();
      nextIsDoubled = true;
    } else {
      discard.add(val);
    }
  }

  return discard;
}

