@pragma('vm:entry-point')
Set<int> findCompanionSeatIndices(String rowStatus) {
  final Set<int> result = {};
  int state = 0;
  int blockStart = -1;

  for (int i = 0; i < rowStatus.length; i++) {
    final String c = rowStatus[i];
    if (state == 0) {
      if (c == 'E') {
        state = 1;
        blockStart = i;
      } else if (c == 'X' || c == 'R') {
        state = 2;
      }
    } else if (state == 1) {
      if (c == 'A') {
        if (i - blockStart >= 2) {
          for (int j = blockStart; j < i; j++) result.add(j);
        }
        state = 0;
      } else if (c == 'X' || c == 'R') {
        state = 2;
      }
    } else {
      if (c == 'A') {
        state = 0;
      }
    }
  }

  if (state == 1 && rowStatus.length - blockStart >= 2) {
    for (int j = blockStart; j < rowStatus.length; j++) {
      result.add(j);
    }
  }
  return result;
}

