@pragma('vm:entry-point')
List<String> minEvenPacketFragments(List<int> allowedSizes, int maxSize) {
  List<int> dpEven = List.filled(maxSize + 1, 999999), dpOdd = List.filled(maxSize + 1, 999999);
  dpEven[0] = 0;
  for (int i = 1; i <= maxSize; i++) {
    for (int c in allowedSizes) {
      if (c > 0 && i >= c) {
        if (dpEven[i - c] != 999999) dpOdd[i] = dpOdd[i] < dpEven[i - c] + 1 ? dpOdd[i] : dpEven[i - c] + 1;
        if (dpOdd[i - c] != 999999) dpEven[i] = dpEven[i] < dpOdd[i - c] + 1 ? dpEven[i] : dpOdd[i - c] + 1;
      }
    }
  }
  return [for (int i = 1; i <= maxSize; i++) "$i: ${dpEven[i] == 999999 ? 0 : dpEven[i]}"];
}

@pragma('vm:entry-point')
