@pragma('vm:entry-point')
List<String> getModularMazePath(int rows, int cols, int step) {
  if (rows <= 0 || cols <= 0) return [];
  int n = rows * cols;
  int a = n;
  int b = step;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  int count = n ~/ a;
  List<String> cells = [];
  for (int i = 0; i < count; i++) {
    int idx = (i * step) % n;
    cells.add('${idx ~/ cols},${idx % cols}');
  }
  cells.sort();
  return cells;
}

@pragma('vm:entry-point')
void main() {
  assert(getModularMazePath(2, 3, 4).toString() == '[0,0, 0,2, 1,1]');
  assert(getModularMazePath(6, 6, 4).length == 9);
  assert(getModularMazePath(4, 4, 8).toString() == '[0,0, 2,0]');
