@pragma('vm:entry-point')
List<String> simulateTelemetryStack(List<String> commands) {
  List<double> stack = [];
  int lastCheckpoint = -1;
  List<String> reports = [];

  for (String cmd in commands) {
    if (cmd.startsWith('SAMPLE ')) {
      stack.add(double.parse(cmd.substring(7)));
    } else if (cmd.startsWith('ACCUMULATE ')) {
      double val = double.parse(cmd.substring(11));
      if (stack.isNotEmpty) {
        stack[stack.length - 1] += val;
      } else {
        stack.add(val);
      }
    } else if (cmd == 'CHECKPOINT') {
      lastCheckpoint = stack.length;
    } else if (cmd == 'ROLLBACK') {
      if (lastCheckpoint == -1) {
        stack.clear();
      } else {
        stack.length = lastCheckpoint;
        lastCheckpoint = -1;
      }
    } else if (cmd == 'REPORT') {
      reports.add(stack.toString());
    }
  }
  return reports;
}

@pragma('vm:entry-point')
void main() {
  assert(simulateTelemetryStack(['SAMPLE 2.0', 'REPORT']).toString() == '[[2.0]]');
  assert(simulateTelemetryStack([]).isEmpty);
