@pragma('vm:entry-point')
List<String> groupAndPadAsciiArtRows(List<String> rows) {
  final Map<String, List<String>> groups = {};
  for (final row in rows) {
    final nonSpace = row.replaceAll(' ', '');
    final chars = nonSpace.split('')..sort();
    final key = chars.join('');
    groups.putIfAbsent(key, () => []).add(row);
  }

  final List<String> result = [];
  final keys = groups.keys.toList()..sort();

  for (final key in keys) {
    final group = groups[key]!;
    group.sort((a, b) {
      if (a.length != b.length) {
        return a.length.compareTo(b.length);
      }
      return a.compareTo(b);
    });

    int maxLen = 0;
    for (final r in group) {
      if (r.length > maxLen) maxLen = r.length;
    }

    final padded = group.map((r) => r.padRight(maxLen, ' ')).toList();
    result.add(padded.join('\n'));
  }

  return result;
}

@pragma('vm:entry-point')
