@pragma('vm:entry-point')
int countValidAsciiSegments(String row, String target, int minLength, int maxLength, int minGap) {
  int count = 0;
  int n = row.length;
  int i = 0;
  while (i < n) {
    if (row[i] == target) {
      int start = i;
      while (i < n && row[i] == target) i++;
      int len = i - start;
      if (len >= minLength && len <= maxLength) {
        int spacesBefore = 0, j = start - 1;
        while (j >= 0 && row[j] == ' ') { spacesBefore++; j--; }
        bool validPrefix = (start == 0) || (spacesBefore >= minGap);
        int spacesAfter = 0, k = i;
        while (k < n && row[k] == ' ') { spacesAfter++; k++; }
        bool validSuffix = (i == n) || (spacesAfter >= minGap);
        if (validPrefix && validSuffix) count++;
      }
    } else {
      i++;
    }
  }
  return count;
}

@pragma('vm:entry-point')
void main() {
  assert(countValidAsciiSegments('  ##   ###  # ', '#', 2, 3, 2) == 2);
  assert(countValidAsciiSegments('', '#', 1, 1, 1) == 0);
  assert(countValidAsciiSegments('###', '#', 3, 3, 0) == 1);
  print('All tests passed!');
}

tests:
