  expect(countValidAsciiSegments('  ##   ###  # ', '#', 2, 3, 2), 2);
  expect(countValidAsciiSegments('', '#', 1, 1, 1), 0);
  expect(countValidAsciiSegments('###', '#', 3, 3, 0), 1);
  expect(countValidAsciiSegments('#  ##', '#', 1, 2, 2), 2);
  expect(countValidAsciiSegments('A##A', '#', 2, 2, 1), 0);
  expect(countValidAsciiSegments('   ', '#', 1, 1, 1), 0);
  expect(countValidAsciiSegments(' # # ', '#', 1, 1, 1), 2);
  expect(countValidAsciiSegments('  ###  ', '#', 2, 4, 2), 1);
