Map<String, int> calculateScaledRecipe(Map<String, int> baseRecipe, int minTotalAmount) {
  if (baseRecipe.isEmpty) return {};

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  int commonDivisor = 0;
  for (int amount in baseRecipe.values) {
    commonDivisor = gcd(commonDivisor, amount);
  }

  if (commonDivisor == 0) {
    return {for (var entry in baseRecipe.entries) entry.key: 0};
  }

  int sumSimplified = 0;
  Map<String, int> simplifiedRecipe = {};
  for (var entry in baseRecipe.entries) {
    int simplifiedAmount = entry.value ~/ commonDivisor;
    simplifiedRecipe[entry.key] = simplifiedAmount;
    sumSimplified += simplifiedAmount;
  }

  int multiplier = (minTotalAmount + sumSimplified - 1) ~/ sumSimplified;
  if (multiplier < 0) multiplier = 0;

  Map<String, int> scaledRecipe = {};
  for (var entry in simplifiedRecipe.entries) {
    scaledRecipe[entry.key] = entry.value * multiplier;
  }

  return scaledRecipe;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateScaledRecipe({'flour': 2, 'sugar': 1}, 10).toString() == '{flour: 8, sugar: 4}');
  assert(calculateScaledRecipe({'water': 3, 'rice': 2}, 21).toString() == '{water: 15, rice: 10}');
  assert(calculateScaledRecipe({'a': 400, 'b': 200}, 150).toString() == '{a: 100, b: 50}');
  print('All tests passed!');
}

