bool hasSingleBitPerRgbChannel(int rgb) {
  int r = (rgb >> 16) & 0xFF;
  int g = (rgb >> 8) & 0xFF;
  int b = rgb & 0xFF;
  bool rValid = r > 0 && (r & (r - 1)) == 0;
  bool gValid = g > 0 && (g & (g - 1)) == 0;
  bool bValid = b > 0 && (b & (b - 1)) == 0;
  return rValid && gValid && bValid;
}

