Map<String, int> findKthShortestMashup(List<int> durations, int k) {
  int n = durations.length;
  if (n < 2 || k < 1 || k > n * (n - 1) ~/ 2) {
    return {'mashupDuration': -1, 'pairCount': 0};
  }
  int low = durations[0] + durations[1];
  int high = durations[n - 2] + durations[n - 1];
  int ans = high;

  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    int count = 0;
    int right = n - 1;
    for (int left = 0; left < n; left++) {
      while (right > left && durations[left] + durations[right] > mid) {
        right--;
      }
      if (right <= left) break;
      count += (right - left);
    }
    if (count >= k) {
      ans = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }

  int countPairs(int limit) {
    int c = 0;
    int r = n - 1;
    for (int l = 0; l < n; l++) {
      while (r > l && durations[l] + durations[r] > limit) {
        r--;
      }
      if (r <= l) break;
      c += (r - l);
    }
    return c;
  }

  return {'mashupDuration': ans, 'pairCount': countPairs(ans) - countPairs(ans - 1)};
}

@pragma('vm:entry-point')
void main() {
  assert(findKthShortestMashup([1, 2, 3, 4], 3).toString() == '{mashupDuration: 5, pairCount: 2}');
  assert(findKthShortestMashup([10, 20], 1).toString() == '{mashupDuration: 30, pairCount: 1}');
  assert(findKthShortestMashup([5, 5, 5, 5], 6).toString() == '{mashupDuration: 10, pairCount: 6}');
  print('All tests passed!');
}

