List<int> processChessUndoLog(List<String> commands) {
  List<int> stack = [];
  for (String cmd in commands) {
    if (cmd == 'UNDO') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (cmd.length == 2) {
      int file = cmd.codeUnitAt(0) - 65;
      int rank = cmd.codeUnitAt(1) - 49;
      if (file >= 0 && file <= 7 && rank >= 0 && rank <= 7) {
        stack.add(rank * 8 + file);
      }
    }
  }
  return stack;
}

