int calculateSameColorOverlapArea(List<int> rects) {
  int totalOverlap = 0;
  int n = rects.length ~/ 7;
  for (int i = 0; i < n; i++) {
    int x1A = rects[i * 7];
    int y1A = rects[i * 7 + 1];
    int x2A = rects[i * 7 + 2];
    int y2A = rects[i * 7 + 3];
    int rA = rects[i * 7 + 4];
    int gA = rects[i * 7 + 5];
    int bA = rects[i * 7 + 6];

    for (int j = i + 1; j < n; j++) {
      if (rA == rects[j * 7 + 4] && gA == rects[j * 7 + 5] && bA == rects[j * 7 + 6]) {
        int x1B = rects[j * 7];
        int y1B = rects[j * 7 + 1];
        int x2B = rects[j * 7 + 2];
        int y2B = rects[j * 7 + 3];

        int left = x1A > x1B ? x1A : x1B;
        int right = x2A < x2B ? x2A : x2B;
        int top = y1A > y1B ? y1A : y1B;
        int bottom = y2A < y2B ? y2A : y2B;

        int overlapX = right > left ? right - left : 0;
        int overlapY = bottom > top ? bottom - top : 0;

        totalOverlap += overlapX * overlapY;
      }
    }
  }
  return totalOverlap;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateSameColorOverlapArea([0, 0, 10, 10, 255, 0, 0, 5, 5, 15, 15, 255, 0, 0]) == 25);
  assert(calculateSameColorOverlapArea([0, 0, 10, 10, 255, 0, 0, 0, 0, 10, 10, 0, 255, 0]) == 0);
  print('All tests passed!');
}

