Set<int> findUniqueRgbWindowSums(List<int> rgbValues, int windowSize) {
  if (rgbValues.isEmpty || windowSize <= 0 || windowSize > rgbValues.length) return {};
  final Set<int> uniqueSums = {};
  int currentSum = 0;
  for (int i = 0; i < rgbValues.length; i++) {
    currentSum += rgbValues[i];
    if (i >= windowSize) currentSum -= rgbValues[i - windowSize];
    if (i >= windowSize - 1) uniqueSums.add(currentSum);
  }
  return uniqueSums;
}

@pragma('vm:entry-point')
