Set<int> extractRoundedCents(String input) {
  Set<int> res = <int>{};
  for (String t in input.split(' ')) {
    if (t.isEmpty) continue;
    String s = t.startsWith('\$') ? t.substring(1) : t;
    List<String> p = s.split('.');
    int d = p[0].isEmpty ? 0 : int.parse(p[0]);
    int c = 0;
    if (p.length > 1) {
      String cp = p[1];
      if (cp.length >= 2) {
        c = int.parse(cp.substring(0, 2));
        if (cp.length >= 3 && int.parse(cp[2]) >= 5) c++;
      } else if (cp.length == 1) {
        c = int.parse(cp) * 10;
      }
    }
    res.add(d * 100 + c);
  }
  return res;
}

@pragma('vm:entry-point')
void main() {
  assert(extractRoundedCents('1.25').length == 1);
  assert(extractRoundedCents('1.255').contains(126));
  assert(extractRoundedCents('').isEmpty);
  print('All tests passed!');
}

