bool isValidServerLogLine(String line) {
  if (line.isEmpty) return false;
  int i = 0;
  if (line[i] != '[') return false;
  i++;

  bool levelMatched = false;
  if (line.startsWith('INFO] ', i)) { i += 6; levelMatched = true; }
  else if (line.startsWith('WARN] ', i)) { i += 6; levelMatched = true; }
  else if (line.startsWith('ERROR] ', i)) { i += 7; levelMatched = true; }
  else if (line.startsWith('DEBUG] ', i)) { i += 7; levelMatched = true; }

  if (!levelMatched) return false;

  if (i >= line.length) return false;

  int c0 = line.codeUnitAt(i);
  bool isLetter = (c0 >= 65 && c0 <= 90) || (c0 >= 97 && c0 <= 122);
  if (!isLetter) return false;
  i++;
  int serviceNameLen = 1;

  while (i < line.length && line[i] != ':') {
    int c = line.codeUnitAt(i);
    bool isAlnumOrHyphen = (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c == 45);
    if (!isAlnumOrHyphen) return false;
    serviceNameLen++;
    i++;
  }

  if (serviceNameLen > 15) return false;

  if (i >= line.length || line[i] != ':') return false;
  i++;

  if (i >= line.length) return false;

  while (i < line.length) {
    int c = line.codeUnitAt(i);
    if (c == 10 || c == 13) return false;
    i++;
  }

  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isValidServerLogLine('[INFO] auth:User logged in') == true);
  assert(isValidServerLogLine('[ERROR] 123db:Fail') == false);
  assert(isValidServerLogLine('[WARN] a:b\n') == false);
  print('All tests passed!');
}

