  expect(calculateSelfAvoidingKnightProbability(0, 0, 2, 0, 2), 0.015625);
  expect(calculateSelfAvoidingKnightProbability(0, 0, 1, 2, 3), 0.001953125);
  expect(calculateSelfAvoidingKnightProbability(4, 4, 4, 4, 0), 1.0);
  expect(calculateSelfAvoidingKnightProbability(0, 0, 7, 7, 0), 0.0);
