@pragma('vm:entry-point')
int findKthLowestThermostatTemp(List<List<int>> schedule, int start, int end, int k) {
  if (schedule.isEmpty || k <= 0 || start > end) return -1;

  int totalMinutes = 0;
  List<int> temps = [];

  for (var interval in schedule) {
    int s = interval[0];
    int e = interval[1];
    int t = interval[2];
    int clipStart = s > start ? s : start;
    int clipEnd = e < end ? e : end;
    if (clipStart <= clipEnd) {
      totalMinutes += (clipEnd - clipStart + 1);
      temps.add(t);
    }
  }

  if (k > totalMinutes) return -1;

  temps.sort();
  List<int> uniqueTemps = [];
  for (int t in temps) {
    if (uniqueTemps.isEmpty || uniqueTemps.last != t) {
      uniqueTemps.add(t);
    }
  }

  int left = 0;
  int right = uniqueTemps.length - 1;
  int ans = -1;

  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int targetTemp = uniqueTemps[mid];
    int count = 0;

    for (var interval in schedule) {
      int t = interval[2];
      if (t <= targetTemp) {
        int s = interval[0];
        int e = interval[1];
        int clipStart = s > start ? s : start;
        int clipEnd = e < end ? e : end;
        if (clipStart <= clipEnd) {
          count += (clipEnd - clipStart + 1);
        }
      }
    }

    if (count >= k) {
      ans = targetTemp;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }

  return ans;
}

