  assert(findKthLowestThermostatTemp([[0, 10, 20], [15, 20, 10]], 5, 18, 4) == 10);
  assert(findKthLowestThermostatTemp([[0, 10, 20], [15, 20, 10]], 5, 18, 5) == 20);
  assert(findKthLowestThermostatTemp([[0, 5, 15]], 10, 20, 1) == -1);
