@pragma('vm:entry-point')
int minKnightObstacleRemovals(List<List<int>> board) {
  int rLen = board.length;
  if (rLen == 0) return -1;
  int cLen = board[0].length;
  if (cLen == 0) return -1;

  List<List<int>> dist = List.generate(rLen, (_) => List.filled(cLen, 999999));
  List<List<int>> q = [[0, 0]];
  dist[0][0] = board[0][0];

  List<List<int>> moves = [
    [-2, -1], [-2, 1], [-1, -2], [-1, 2],
    [1, -2], [1, 2], [2, -1], [2, 1]
  ];

  while (q.isNotEmpty) {
    var curr = q.removeAt(0);
    int r = curr[0], c = curr[1];

    if (r == rLen - 1 && c == cLen - 1) {
      return dist[r][c];
    }

    for (var m in moves) {
      int nr = r + m[0], nc = c + m[1];
      if (nr >= 0 && nr < rLen && nc >= 0 && nc < cLen) {
        int cost = board[nr][nc];
        if (dist[r][c] + cost < dist[nr][nc]) {
          dist[nr][nc] = dist[r][c] + cost;
          if (cost == 0) {
            q.insert(0, [nr, nc]);
          } else {
            q.add([nr, nc]);
          }
        }
      }
    }
  }
  return dist[rLen - 1][cLen - 1] == 999999 ? -1 : dist[rLen - 1][cLen - 1];
}

