bool areCellsConnected(int cell1, int cell2, int direction) {
  int wallMask = 0xF;
  int c1 = cell1 & wallMask;
  int c2 = cell2 & wallMask;
  int opposite = (direction + 2) % 4;
  int mask1 = 1 << direction;
  int mask2 = 1 << opposite;
