Set<int> findConsecutiveItemIds(List<int> sortedIds) {
  Set<int> result = {};
  int left = 0;
  for (int right = 0; right < sortedIds.length; right++) {
    while (right > left && sortedIds[right] - sortedIds[left] > right - left) {
      left++;
    }
    if (right - left + 1 >= 3) {
      for (int i = left; i <= right; i++) {
        result.add(sortedIds[i]);
      }
    }
  }
  return result;
}

