@pragma('vm:entry-point')
bool verifyNickelRleChecksum(List<int> cents, String expectedRle) {
  if (cents.isEmpty) return expectedRle.isEmpty;

  // Round each cent value to nearest nickel (5 cents) using half-up rounding
  // For non-negative c: round((c / 5)) * 5 is approximated by ((c + 2) ~/ 5) * 5
  List<int> rounded = [];
  for (int c in cents) {
    rounded.add(((c + 2) ~/ 5) * 5);
  }

  // Run-length encode the rounded sequence as "count_value" pairs joined by "|"
  StringBuffer sb = StringBuffer();
  int i = 0;
  while (i < rounded.length) {
    int count = 1;
    while (i + count < rounded.length && rounded[i + count] == rounded[i]) {
      count++;
    }
    if (sb.isNotEmpty) sb.write('|');
    sb.write('${count}_${rounded[i]}');
    i += count;
  }

  return sb.toString() == expectedRle;
}

@pragma('vm:entry-point')
void main() {
  assert(verifyNickelRleChecksum([3], '1_5') == true);
  assert(verifyNickelRleChecksum([], '') == true);
  assert(verifyNickelRleChecksum([5], '1_0') == false);
  print('All tests passed!');
}

