@pragma('vm:entry-point')
List<int> findLedgerWindowMatches(List<int> entries, int windowSize, int targetSum) {
  if (entries.length < windowSize || windowSize <= 0) return [];
  List<int> result = [];
  int windowSum = 0;
  for (int i = 0; i < entries.length; i++) {
    windowSum += entries[i];
    if (i >= windowSize) {
      windowSum -= entries[i - windowSize];
    }
    if (i >= windowSize - 1 && windowSum == targetSum) {
      result.add(i - windowSize + 1);
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(findLedgerWindowMatches([10, 20, 30, 40, 50], 2, 50).toString() == "[1]");
  assert(findLedgerWindowMatches([5, 5, 5, 5], 2, 10).toString() == "[0, 1, 2]");
