@pragma('vm:entry-point')
List<int> reassembleNestedPacketSizes(List<int> packetStream) {
  List<int> stack = [];
  for (int value in packetStream) {
    if (value > 0) {
      stack.add(value);
    } else if (value < 0) {
      stack.add(value);
    } else {
      int markerIndex = -1;
      for (int i = stack.length - 1; i >= 0; i--) {
        if (stack[i] < 0) {
          markerIndex = i;
          break;
        }
      }
      if (markerIndex >= 0) {
        int sum = 0;
        while (stack.length > markerIndex) {
          int popped = stack.removeLast();
          if (popped > 0) {
            sum += popped;
          } else {
            sum += -popped;
          }
        }
        stack.add(sum);
      }
    }
  }
  return stack;
}

@pragma('vm:entry-point')
void main() {
  assert(reassembleNestedPacketSizes([100, -5, 50, 0, 200]).toString() == '[100, 55, 200]');
  assert(reassembleNestedPacketSizes([-2, 10, -3, 20, 30, 0, 40, 0]).toString() == '[105]');
  assert(reassembleNestedPacketSizes([]).toString() == '[]');
  print('All tests passed!');
}

