bool hasOneCharFixInSortedDict(List<String> dict, String query) {
  for (int i = 0; i < query.length; i++) {
    for (int c = 97; c <= 122; c++) {
      if (c == query.codeUnitAt(i)) continue;
      String candidate = query.substring(0, i) + String.fromCharCode(c) + query.substring(i + 1);
      int lo = 0, hi = dict.length - 1;
      while (lo <= hi) {
        int mid = (lo + hi) ~/ 2;
        int cmp = dict[mid].compareTo(candidate);
        if (cmp == 0) return true;
        if (cmp < 0) lo = mid + 1; else hi = mid - 1;
      }
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasOneCharFixInSortedDict(['bat', 'cat', 'hat'], 'dat') == true);
  assert(hasOneCharFixInSortedDict(['bat', 'cat', 'hat'], 'dog') == false);
