  Map<String, int> charRow = {};
  Map<String, int> charCol = {};
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      String ch = grid[r][c];
      charRow[ch] = r;
      charCol[ch] = c;
    }
  }
  int rows = grid.length;
  int cols = grid.isEmpty ? 0 : grid[0].length;
  List<int> dr = [-1, 1, 0, 0];
  List<int> dc = [0, 0, -1, 1];
  List<String> results = [];
  for (int i = 0; i < word.length; i++) {
    String ch = word[i];
    if (!charRow.containsKey(ch)) continue;
    int r = charRow[ch]!;
    int c = charCol[ch]!;
    for (int d = 0; d < 4; d++) {
      int nr = r + dr[d];
      int nc = c + dc[d];
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      String edited = word.substring(0, i) + grid[nr][nc] + word.substring(i + 1);
      results.add(edited);
    }
  }
  results.sort();
  List<String> unique = [];
  String prev = '';
  for (String s in results) {
    if (s != prev) {
      unique.add(s);
      prev = s;
    }
  }
  return unique;
}

@pragma('vm:entry-point')
