  assert(generateGridNeighborEdits([["A","B"],["C","D"]], "AC").toString() == "[AA, AD, BC, CC]");
  assert(generateGridNeighborEdits([["A"]], "A").isEmpty);
  assert(generateGridNeighborEdits([["A","B"],["C","D"]], "XZ").length == 0);
  print('All tests passed!');
}

