Set<int> findConflictDepartureMinutes(List<int> frequencies) {
  Set<int> conflicts = {};
  if (frequencies.length < 2) {
    return conflicts;
  }
  for (int minute = 0; minute < 60; minute++) {
    int simultaneousCount = 0;
    for (int freq in frequencies) {
      if (freq > 0 && minute % freq == 0) {
        simultaneousCount++;
        if (simultaneousCount >= 2) {
          conflicts.add(minute);
          break;
        }
      }
    }
  }
  return conflicts;
}

