@pragma('vm:entry-point')
List<String> orderElevatorRequests(int currentFloor, int direction, List<int> requests, Set<int> expressFloors) {
  if (requests.isEmpty) return <String>[];
  String label(int f) => f < 0 ? 'B${-f}' : f == 0 ? 'G' : '$f';

  List<int> scan(List<int> floors, int dir) {
    if (floors.isEmpty) return <int>[];
    var same = floors.where((f) => (f - currentFloor) * dir > 0).toList();
    var opp = floors.where((f) => (f - currentFloor) * dir < 0).toList();
    var here = floors.where((f) => f == currentFloor).toList();
    same.sort(dir > 0 ? (a, b) => a.compareTo(b) : (a, b) => b.compareTo(a));
    opp.sort(dir > 0 ? (a, b) => b.compareTo(a) : (a, b) => a.compareTo(b));
    return [...here, ...same, ...opp];
  }

  Set<int> seen = {};
  List<int> express = [], normal = [];
  for (int f in requests) {
    if (seen.add(f)) {
      (expressFloors.contains(f) ? express : normal).add(f);
    }
  }

  return [...scan(express, direction), ...scan(normal, direction)].map(label).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(orderElevatorRequests(1, 1, [3, -1, 5, 2], {-1, 5}).toString() == '[5, B1, 2, 3]');
  assert(orderElevatorRequests(3, -1, [1, 5, 0, -2], {5}).toString() == '[5, 1, G, B2]');
  assert(orderElevatorRequests(0, 1, [], {}).toString() == '[]');
  print('All tests passed!');
}

