@pragma('vm:entry-point')
String formatTideFrequencyReport(List<double> heights) {
  Map<double, int> freq = {};
  for (double h in heights) {
    freq[h] = (freq[h] ?? 0) + 1;
  }
  List<double> sorted = freq.keys.toList()..sort();
  List<String> parts = [];
  for (double h in sorted) {
    parts.add('${h}m:${freq[h]}');
  }
  return parts.join(' ');
}

@pragma('vm:entry-point')
