  assert(formatTideFrequencyReport([1.5, 2.0, 1.5, 3.0, 2.0, 2.0]) == '1.5m:2 2.0m:3 3.0m:1');
  assert(formatTideFrequencyReport([0.5, 0.5, 0.5]) == '0.5m:3');
