  assert(countDryCellsAtIntervalEndpoints([[5, 3], [2, 8]], [], 2, 5, 0) == 3);
  assert(countDryCellsAtIntervalEndpoints([[5, 3], [2, 8]], [[3, 0, 4]], 2, 5, 0) == 1);
