@pragma('vm:entry-point')
List<String> hashBucketSnapshots(int numBuckets, List<String> ops) {
  List<List<String>> buckets = List.generate(numBuckets, (_) => <String>[]);
  List<int> undoIdx = [];
  List<List<String>> undoPrev = [];
  List<String> snapshots = [];
  for (String op in ops) {
    if (op == 'undo') {
      if (undoIdx.isNotEmpty) {
        int i = undoIdx.removeLast();
        buckets[i] = undoPrev.removeLast();
      }
    } else if (op == 'snap') {
      String s = '';
      for (int i = 0; i < buckets.length; i++) {
        if (i > 0) s += ',';
        s += buckets[i].length.toString();
      }
      snapshots.add(s);
    } else if (op.startsWith('put:')) {
      String key = op.substring(4);
      int h = 0;
      for (int c in key.codeUnits) {
        h = (h + c) % numBuckets;
      }
      undoIdx.add(h);
      undoPrev.add(List.of(buckets[h]));
      buckets[h].add(key);
    }
  }
  return snapshots;
}

@pragma('vm:entry-point')
void main() {
  assert(hashBucketSnapshots(3, ['put:apple', 'snap']).first == '0,0,1');
  assert(hashBucketSnapshots(2, []).toString() == '[]');
  assert(hashBucketSnapshots(4, ['undo', 'snap']).first == '0,0,0,0');
  print('All tests passed!');
}

