@pragma('vm:entry-point')
bool isValidThermostatSchedule(String schedule) {
  if (schedule.isEmpty) return false;
  final entries = schedule.split(';');
  int? prevTime;
  int? prevTemp;
  for (var entry in entries) {
    if (entry.isEmpty) return false;
    final atIdx = entry.indexOf('@');
    if (atIdx < 0) return false;
    final timePart = entry.substring(0, atIdx);
    final tempPart = entry.substring(atIdx + 1);
    final colonIdx = timePart.indexOf(':');
    if (colonIdx != 2) return false;
    final hourStr = timePart.substring(0, colonIdx);
    final minStr = timePart.substring(colonIdx + 1);
    if (hourStr.length != 2 || minStr.length != 2) return false;
    final hour = int.tryParse(hourStr);
    final min = int.tryParse(minStr);
    if (hour == null || min == null) return false;
    if (hour < 0 || hour > 23 || min < 0 || min > 59) return false;
    final timeVal = hour * 60 + min;
    final temp = int.tryParse(tempPart);
    if (temp == null) return false;
    if (temp < 50 || temp > 90) return false;
    if (prevTime != null) {
      if (timeVal <= prevTime) return false;
      final delta = (temp - prevTemp!).abs();
      if (delta > 15) return false;
    }
    prevTime = timeVal;
    prevTemp = temp;
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isValidThermostatSchedule('06:30@72;07:00@75') == true);
  assert(isValidThermostatSchedule('06:30@72;06:30@75') == false);
  assert(isValidThermostatSchedule('') == false);
  print('All tests passed!');
}

