@pragma('vm:entry-point')
String dnaComposition(String dna) {
  final counts = <String, int>{};
  for (final base in dna.split('')) {
    if ('ATCG'.contains(base)) {
      counts[base] = (counts[base] ?? 0) + 1;
    }
  }
  const order = ['A', 'C', 'G', 'T'];
  final parts = <String>[];
  for (final base in order) {
    final c = counts[base];
    if (c != null && c > 0) parts.add('$base:$c');
  }
  return parts.join(' ');
}

