Map<String, int> longestLowTidePeriod(List<int> dailyHeights, int threshold) {
  if (dailyHeights.isEmpty) return {"start": -1, "duration": 0};
  int maxStart = -1;
  int maxDur = 0;
  int currStart = -1;
  int currDur = 0;
  for (int i = 0; i < dailyHeights.length; i++) {
    if (dailyHeights[i] <= threshold) {
      if (currDur == 0) currStart = i;
      currDur++;
      if (currDur > maxDur) {
        maxDur = currDur;
        maxStart = currStart;
      }
    } else {
      currDur = 0;
    }
  }
  return {"start": maxStart, "duration": maxDur};
}

