  final candidate = parseTideLog;

  expect(candidate('2.0,1.5,1.0,1.5'), 'VALID:1t');
  expect(candidate('1.0'), 'INVALID:short');
  expect(candidate('1.0,1.0,1.0'), 'INVALID:2a');
  expect(candidate('1.0,0.5,1.0'), 'VALID:1t');
}

