@pragma('vm:entry-point')
bool isSatellitePassSequenceValid(List<int> events) {
  List<int> stack = [];
  Set<int> active = {};
  int maxConcurrent = 0;
  int current = 0;
  for (int e in events) {
    if (e > 0) {
      if (active.contains(e)) return false;
      stack.add(e);
      active.add(e);
      current++;
      if (current > maxConcurrent) maxConcurrent = current;
    } else {
      int id = -e;
      if (stack.isEmpty || stack.last != id) return false;
      stack.removeLast();
      active.remove(id);
      current--;
    }
  }
  if (maxConcurrent > 3) return false;
  return stack.isEmpty;
}

@pragma('vm:entry-point')
void main() {
  assert(isSatellitePassSequenceValid([1, 2, -2, -1]) == true);
  assert(isSatellitePassSequenceValid([1, 2, -1, -2]) == false);
