@pragma('vm:entry-point')
int resolveChessMoveUndos(List<int> moves) {
  List<int> stack = [];
  for (int move in moves) {
    if (move < 0 || move >= 64) {
      if (stack.isNotEmpty) stack.removeLast();
      continue;
    }
    int row = move ~/ 8;
    int col = move % 8;
    bool isDark = (row + col) % 2 == 1;
    if (stack.isEmpty) {
      stack.add(move);
      continue;
    }
    int prev = stack.last;
    int prow = prev ~/ 8;
    int pcol = prev % 8;
    bool pDark = (prow + pcol) % 2 == 1;
    if (isDark != pDark) {
      stack.add(move);
    } else {
      stack.removeLast();
    }
  }
  return stack.length;
}

@pragma('vm:entry-point')
