@pragma('vm:entry-point')
List<int> computeClosestScaledRecipe(List<int> baseAmounts, int targetServings) {
  if (baseAmounts.isEmpty) return [];
  int n = baseAmounts.length;
  List<int> dp = List.filled(targetServings + 1, -1);
  dp[0] = 0;
  List<List<int>> prev = List.generate(targetServings + 1, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    int amt = baseAmounts[i];
    for (int s = amt; s <= targetServings; s++) {
      if (dp[s - amt] != -1) {
        int candidate = dp[s - amt] + 1;
        if (dp[s] == -1 || candidate < dp[s]) {
          dp[s] = candidate;
          for (int k = 0; k < n; k++) prev[s][k] = prev[s - amt][k];
          prev[s][i] += amt;
        }
      }
    }
  }
  int best = 0;
  int bestDiff = (targetServings - 0).abs();
  for (int s = 0; s <= targetServings; s++) {
    if (dp[s] != -1) {
      int diff = (targetServings - s).abs();
      if (diff < bestDiff || (diff == bestDiff && s > best)) {
        best = s;
        bestDiff = diff;
      }
    }
  }
  return prev[best];
}

@pragma('vm:entry-point')
void main() {
  assert(computeClosestScaledRecipe([2, 3], 10).toString() == '[6, 3]');
  assert(computeClosestScaledRecipe([], 5).toString() == '[]');
