List<int> computeStateDurations(List<int> samples) {
  if (samples.isEmpty) return [];
  int currentState = -1;
  List<int> durations = [];
  int count = 0;
  for (int i = 0; i < samples.length; i++) {
    int val = samples[i];
    int newState;
    if (val < 10) {
      newState = 0;
    } else if (val <= 50) {
      newState = 1;
    } else {
      newState = 2;
    }
    if (newState != currentState) {
      if (currentState != -1) {
        durations.add(count);
      }
      currentState = newState;
      count = 1;
    } else {
      count++;
    }
  }
  if (currentState != -1) {
    durations.add(count);
  }
  return durations;
}

