@pragma('vm:entry-point')
bool canSegmentIntoMorseSymbols(String sequence, List<String> symbols) {
  if (sequence.isEmpty) return true;
  if (symbols.isEmpty) return false;
  int n = sequence.length;
  List<bool> dp = List<bool>.filled(n + 1, false);
  dp[0] = true;
  Set<String> symbolSet = symbols.toSet();
  int maxLen = 0;
  for (String s in symbols) {
    if (s.length > maxLen) maxLen = s.length;
  }
  for (int i = 1; i <= n; i++) {
    for (int j = i - 1; j >= 0 && i - j <= maxLen; j--) {
      if (dp[j]) {
        String sub = sequence.substring(j, i);
        if (symbolSet.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(canSegmentIntoMorseSymbols(".-", [".-", "--"]) == true);
  assert(canSegmentIntoMorseSymbols("", ["."]) == true);
