Map<String, int> calculateMaxStreaksByLevel(List<String> logs) {
  Map<String, int> maxStreak = {};
  if (logs.isEmpty) return maxStreak;
  String prev = logs[0];
  int count = 1;
  maxStreak[prev] = 1;
  for (int i = 1; i < logs.length; i++) {
    if (logs[i] == prev) {
      count++;
      if (count > maxStreak[prev]!) maxStreak[prev] = count;
    } else {
      prev = logs[i];
      count = 1;
      if (!maxStreak.containsKey(prev)) maxStreak[prev] = 1;
    }
  }
  return maxStreak;
}

