Map<String, int> locateSectionIndices(List<String> shelfCodes, String section) {
  int first = -1;
  int last = -1;
  int low = 0;
  int high = shelfCodes.length - 1;
  while (low <= high) {
    int mid = low + ((high - low) ~/ 2);
    if (shelfCodes[mid].startsWith(section)) {
      first = mid;
      high = mid - 1;
    } else if (shelfCodes[mid].compareTo(section) < 0) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  low = 0;
  high = shelfCodes.length - 1;
  while (low <= high) {
    int mid = low + ((high - low) ~/ 2);
    if (shelfCodes[mid].startsWith(section)) {
      last = mid;
      low = mid + 1;
    } else if (shelfCodes[mid].compareTo(section) < 0) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return {'first': first, 'last': last};
}

