@pragma('vm:entry-point')
int evaluateKnightSequence(String input) {
  int state = 0;
  String file = '';
  int rank = 0;
  List<int> xs = [];
  List<int> ys = [];
  for (int i = 0; i < input.length; i++) {
    String c = input[i];
    if (state == 0) {
      int code = c.codeUnitAt(0);
      if (code >= 97 && code <= 104) {
        state = 1;
        file = c;
      }
    } else if (state == 1) {
      int code = c.codeUnitAt(0);
      if (code >= 49 && code <= 56) {
        rank = int.parse(c);
        int x = file.codeUnitAt(0) - 97;
        int y = rank - 1;
        xs.add(x);
        ys.add(y);
        state = 0;
      } else {
        state = 0;
      }
    }
  }
  int count = 0;
  for (int j = 1; j < xs.length; j++) {
    int dx = (xs[j] - xs[j - 1]).abs();
    int dy = (ys[j] - ys[j - 1]).abs();
    if ((dx == 1 && dy == 2) || (dx == 2 && dy == 1)) {
      count++;
    }
  }
  return count;
}

