@pragma('vm:entry-point')
Set<int> findBuriedItems(List<List<int>> items) {
  // Each item is [id, x1, y1, x2, y2] with x1 < x2 and y1 < y2.
  // An item is "buried" if its whole rectangle is covered by the
  // union of all OTHER items' rectangles (coordinate-compression check).
  final buried = <int>{};
  for (var i = 0; i < items.length; i++) {
    final r = items[i];
    final xs = <int>{r[1], r[3]};
    final ys = <int>{r[2], r[4]};
    for (var j = 0; j < items.length; j++) {
      if (j == i) continue;
      final o = items[j];
      if (o[1] > r[1] && o[1] < r[3]) xs.add(o[1]);
      if (o[3] > r[1] && o[3] < r[3]) xs.add(o[3]);
      if (o[2] > r[2] && o[2] < r[4]) ys.add(o[2]);
      if (o[4] > r[2] && o[4] < r[4]) ys.add(o[4]);
    }
    final xList = xs.toList()..sort();
    final yList = ys.toList()..sort();
    var fully = true;
    for (var a = 0; a < xList.length - 1 && fully; a++) {
      for (var b = 0; b < yList.length - 1 && fully; b++) {
        final cx1 = xList[a], cx2 = xList[a + 1];
        final cy1 = yList[b], cy2 = yList[b + 1];
        var covered = false;
        for (var j = 0; j < items.length && !covered; j++) {
          if (j == i) continue;
          final o = items[j];
          if (o[1] <= cx1 && o[3] >= cx2 && o[2] <= cy1 && o[4] >= cy2) {
            covered = true;
          }
        }
        if (!covered) fully = false;
      }
    }
    if (fully) buried.add(r[0]);
  }
  return buried;
}

@pragma('vm:entry-point')
void main() {
  assert(findBuriedItems([[1, 1, 1, 2, 2], [2, 0, 0, 3, 3]]).contains(1));
  assert(findBuriedItems([[1, 0, 0, 2, 2]]).isEmpty);
  assert(findBuriedItems([[1, 0, 0, 4, 2], [2, 0, 0, 2, 2], [3, 2, 0, 4, 2]]).length == 3);
  print('All tests passed!');
