void main() {
  assert(analyzeRgbPixelGroups([]).toString() == '{dark: 0, mid: 0, bright: 0, redDominant: 0, greenDominant: 0, blueDominant: 0, clipped: 0}');
  assert(analyzeRgbPixelGroups([[255, 0, 0], [255, 0, 0], [0, 0, 255]])['blueDominant'] == 1);
  assert(analyzeRgbPixelGroups([[300, 10, 10]])['clipped'] == 1);
