@pragma('vm:entry-point')
Map<String, int> summarizeTidePatterns(List<int> readings, int calmBand) {
  final Map<String, int> result = {
    'rises': 0,
    'falls': 0,
    'reversals': 0,
    'calmSegments': 0,
  };

  if (readings.isEmpty) {
    return result;
  }

  final List<int> compressed = <int>[readings.first];
  for (int i = 1; i < readings.length; i++) {
    if (readings[i] != readings[i - 1]) {
      compressed.add(readings[i]);
    }
  }

  int previousDirection = 0;

  for (int i = 1; i < compressed.length; i++) {
    final int diff = compressed[i] - compressed[i - 1];
    final int direction = diff > 0 ? 1 : -1;

    if (diff > 0) {
      result['rises'] = result['rises']! + diff;
    } else {
      result['falls'] = result['falls']! + (-diff);
    }

    if (previousDirection != 0 && previousDirection != direction) {
      result['reversals'] = result['reversals']! + 1;
    }

    previousDirection = direction;
  }

  int segments = 1;
  int segmentMin = readings.first;
  int segmentMax = readings.first;

  for (int i = 1; i < readings.length; i++) {
    final int value = readings[i];

    if (value < segmentMin) {
      segmentMin = value;
    }
    if (value > segmentMax) {
      segmentMax = value;
    }

    if (segmentMax - segmentMin > calmBand) {
      segments++;
      segmentMin = value;
      segmentMax = value;
    }
  }

  result['calmSegments'] = segments;
  return result;
}

