  assert(summarizeTidePatterns([], 2).toString() == '{rises: 0, falls: 0, reversals: 0, calmSegments: 0}');
  assert(summarizeTidePatterns([3, 3, 5, 2, 2, 4], 2).toString() == '{rises: 4, falls: 3, reversals: 2, calmSegments: 2}');
