@pragma('vm:entry-point')
int earliestElevatorAlignment(List<int> requestedFloors, List<int> serviceCycles) {
  if (requestedFloors.length != serviceCycles.length) {
    return -1;
  }
  if (requestedFloors.isEmpty) {
    return 0;
  }

  int modInverse(int a, int mod) {
    int b = mod;
    int u = 1;
    int v = 0;

    while (b != 0) {
      int t = a ~/ b;
      int nextA = a - t * b;
      a = b;
      b = nextA;

      int nextU = u - t * v;
      u = v;
      v = nextU;
    }

    u %= mod;
    if (u < 0) {
      u += mod;
    }
    return u;
  }

  int x = ((requestedFloors[0] % serviceCycles[0]) + serviceCycles[0]) % serviceCycles[0];
  int m = serviceCycles[0];

  for (int i = 1; i < requestedFloors.length; i++) {
    int a = ((requestedFloors[i] % serviceCycles[i]) + serviceCycles[i]) % serviceCycles[i];
    int n = serviceCycles[i];

    int aa = m;
    int bb = n;
    while (bb != 0) {
      int temp = aa % bb;
      aa = bb;
      bb = temp;
    }
    int g = aa;

    int diff = a - x;
    if (diff % g != 0) {
      return -1;
    }

    int reducedM = m ~/ g;
    int reducedN = n ~/ g;
    int inverse = modInverse(reducedM % reducedN, reducedN);

    int step = (((diff ~/ g) % reducedN) + reducedN) % reducedN;
    step = (step * inverse) % reducedN;

    int lcm = reducedM * n;
    x = (x + m * step) % lcm;
    if (x < 0) {
      x += lcm;
    }
    m = lcm;
  }

  return x;
}

@pragma('vm:entry-point')
void main() {
  assert(earliestElevatorAlignment([5, 8], [6, 9]) == 17);
  assert(earliestElevatorAlignment([2, 3, 2], [3, 5, 7]) == 23);
  assert(earliestElevatorAlignment([1, 2], [2, 4]) == -1);
  print('All tests passed!');
}

