@pragma('vm:entry-point')
List<int> longestBalancedAsciiWindows(List<String> rows, int maxDots) {
  List<int> results = [];

  for (String row in rows) {
    int left = 0;
    int dots = 0;
    int diff = 0;
    int best = 0;

    Map<int, List<int>> positions = {
      0: [0]
    };
    Map<int, int> heads = {
      0: 0
    };

    for (int right = 0; right < row.length; right++) {
      String ch = row[right];

      if (ch == '.') {
        dots++;
      }

      if (ch == '/') {
        diff++;
      } else if (ch == '\\') {
        diff--;
      }

      while (dots > maxDots) {
        if (row[left] == '.') {
          dots--;
        }
        left++;
      }

      positions.putIfAbsent(diff, () => []);
      heads.putIfAbsent(diff, () => 0);

      List<int> list = positions[diff]!;
      int head = heads[diff]!;

      while (head < list.length && list[head] < left) {
        head++;
      }

      heads[diff] = head;

      if (head < list.length) {
        int length = (right + 1) - list[head];
        if (length > best) {
          best = length;
        }
      }

      list.add(right + 1);
    }

    results.add(best);
  }

  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(longestBalancedAsciiWindows(["/\\"], 0).toString() == "[2]");
  assert(longestBalancedAsciiWindows(["..//\\\\.."], 1).toString() == "[5]");
  assert(longestBalancedAsciiWindows(["", "/./\\\\"], 1).toString() == "[0, 5]");
  print('All tests passed!');
}

