@pragma('vm:entry-point')
List<int> scanAsciiArtRows(List<String> rows) {
  List<int> results = <int>[];

  for (String row in rows) {
    int current = 0;
    int number = 0;
    bool hasNumber = false;
    bool invert = false;

    List<int> valueStack = <int>[];
    List<int> repeatStack = <int>[];

    for (int i = 0; i < row.length; i++) {
      String ch = row[i];

      if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        number = (number * 10) + (ch.codeUnitAt(0) - 48);
        hasNumber = true;
        continue;
      }

      int repeat = hasNumber ? number : 1;

      if (ch == '[') {
        valueStack.add(current);
        repeatStack.add(repeat);
        current = 0;
      } else if (ch == ']') {
        if (valueStack.isNotEmpty && repeatStack.isNotEmpty) {
          int parent = valueStack.removeLast();
          int groupRepeat = repeatStack.removeLast();
          current = parent + current * groupRepeat;
        }
      } else if (ch == '!') {
        invert = !invert;
      } else if (ch == '#') {
        current += invert ? 0 : repeat;
      } else if (ch == '.') {
        current += invert ? repeat : 0;
      } else if (ch == '@') {
        current += repeat * 2;
      }

      number = 0;
      hasNumber = false;
    }

    results.add(current);
  }

