void main() {
  assert(analyzeThermostatSchedule([20, 22, 24, 21], 6).toString() == '{syncStep: 1, primeSetpoints: 0, transitionCode: 6}');
  assert(analyzeThermostatSchedule([2, 3, 5, 7], 8).toString() == '{syncStep: 1, primeSetpoints: 4, transitionCode: 7}');
  assert(analyzeThermostatSchedule([], 10).toString() == '{syncStep: 10, primeSetpoints: 0, transitionCode: 0}');
  print('All tests passed!');
}

