@pragma('vm:entry-point')
double rgbUndoBlendScore(List<String> operations) {
  List<List<int>> stack = [];
  List<List<List<int>>> history = [];

  List<List<int>> cloneStack(List<List<int>> source) {
    return source.map((pixel) => List<int>.from(pixel)).toList();
  }

  for (String op in operations) {
    List<String> parts = op.split(' ');

    if (parts[0] == 'UNDO') {
      if (history.isNotEmpty) {
        stack = history.removeLast();
      }
      continue;
    }

    bool changed = false;
    List<List<int>> before = cloneStack(stack);

    if (parts[0] == 'SET' && parts.length == 4) {
      int r = int.parse(parts[1]);
      int g = int.parse(parts[2]);
      int b = int.parse(parts[3]);
      stack.add([r, g, b]);
      changed = true;
    } else if (parts[0] == 'DUP' && stack.isNotEmpty) {
      stack.add(List<int>.from(stack.last));
      changed = true;
    } else if (parts[0] == 'SWAP' && stack.length >= 2) {
      List<int> top = stack.removeLast();
      List<int> next = stack.removeLast();
      stack.add(top);
      stack.add(next);
      changed = true;
    } else if (parts[0] == 'MIX' && stack.length >= 2) {
      List<int> a = stack.removeLast();
      List<int> b = stack.removeLast();
      stack.add([
        (a[0] + b[0]) ~/ 2,
        (a[1] + b[1]) ~/ 2,
        (a[2] + b[2]) ~/ 2,
      ]);
      changed = true;
    }

    if (changed) {
      history.add(before);
    }
  }

  int total = 0;
  for (int i = 0; i < stack.length; i++) {
    List<int> p = stack[i];
    total += (p[0] + 2 * p[1] + 3 * p[2]) * (i + 1);
  }

  return total / 4.0;
}

@pragma('vm:entry-point')
void main() {
  assert(rgbUndoBlendScore(["SET 4 8 12"]) == 14.0);
  assert(rgbUndoBlendScore(["SET 8 0 0", "DUP"]) == 6.0);
  assert(rgbUndoBlendScore(["SET 8 4 0", "SET 0 4 8", "MIX"]) == 6.0);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = rgbUndoBlendScore;

  expect(candidate([]), 0.0);
  expect(candidate(["SET 4 8 12"]), 14.0);
  expect(candidate(["SET 8 0 0", "DUP"]), 6.0);
  expect(candidate(["SET 8 4 0", "SET 0 4 8", "MIX"]), 6.0);
  expect(candidate(["SET 12 0 0", "SET 0 12 0", "UNDO"]), 3.0);
  expect(candidate(["SET 16 0 0", "DUP", "MIX", "UNDO"]), 12.0);
  expect(candidate(["MIX", "SET 2 2 2", "UNDO"]), 0.0);
