double decodeSoilMoistureTotal(String encodedGrid) {
  double total = 0.0;
  for (int i = 0; i < encodedGrid.length; i += 2) {
    String cell = encodedGrid[i];
    int count = int.parse(encodedGrid[i + 1]);
    if (cell == 'W') {
