@pragma('vm:entry-point')
double trainMinuteHarmony(List<int> departures, int cycleMinutes) {
  if (departures.isEmpty || cycleMinutes <= 1) {
    return 0.0;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    return a.abs();
  }

  bool isPrime(int n) {
    if (n < 2) {
      return false;
    }
    for (int i = 2; i * i <= n; i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
  }

  double score = 0.0;

  for (int i = 0; i < departures.length; i++) {
    int current = departures[i] % cycleMinutes;
    int next = departures[(i + 1) % departures.length] % cycleMinutes;

    int gap = next - current;
    if (gap <= 0) {
      gap += cycleMinutes;
    }

    int sharedFactor = gcd(gap, cycleMinutes);

    if (isPrime(sharedFactor)) {
      score += 0.5;
    } else if (sharedFactor == 1) {
      score += 0.25;
    }

    if (isPrime(gap)) {
      score += 0.25;
    }
  }

  return score;
}

