  assert(trainMinuteHarmony([0, 7, 20], 30) == 1.0);
  assert(trainMinuteHarmony([0, 7], 14) == 1.5);
  assert(trainMinuteHarmony([], 60) == 0.0);
  print('All tests passed!');
}

