  assert(tideSlackDuration([1, 4, 6], [2.0, 3.0, 2.5], 10) == 12.0);
  assert(tideSlackDuration([0], [1.5], 8) == 9.5);
  assert(tideSlackDuration([0, 3], [1.0, 5.0], 6) == 4.0);
  print('All tests passed!');
}

