@pragma('vm:entry-point')
double theaterChartSignal(String encodedChart) {
  if (encodedChart.isEmpty) {
    return 0.0;
  }

  List<String> rows = [];
  String currentRow = '';
  int i = 0;

  while (i < encodedChart.length) {
    String ch = encodedChart[i];

    if (ch == '|') {
      rows.add(currentRow);
      currentRow = '';
      i++;
      continue;
    }

    if (ch != 'O' && ch != 'E' && ch != 'R') {
      return -1.0;
    }

    i++;
    String countText = '';
    while (i < encodedChart.length && encodedChart[i] != '|' && encodedChart.codeUnitAt(i) >= 48 && encodedChart.codeUnitAt(i) <= 57) {
      countText += encodedChart[i];
      i++;
    }

    if (countText.isEmpty) {
      return -1.0;
    }

    int count = int.parse(countText);
    if (count <= 0) {
      return -1.0;
    }

    currentRow += ch * count;
  }

  rows.add(currentRow);

  double score = 0.0;

  for (String row in rows) {
    if (row.isEmpty) {
      continue;
    }

    if (row[0] == 'O') {
      score += 1.0;
    }

    if (row.length > 1 && row[row.length - 1] == 'O') {
      score += 1.0;
    }

    for (int j = 0; j < row.length; j++) {
      if (row[j] == 'R') {
        bool nearOccupied = (j > 0 && row[j - 1] == 'O') ||
            (j < row.length - 1 && row[j + 1] == 'O');
        if (nearOccupied) {
          score += 0.5;
        }
      }
    }
  }

  return score;
}

