@pragma('vm:entry-point')
List<int> smoothestTideRoute(List<List<int>> tideHeights) {
  if (tideHeights.isEmpty || tideHeights[0].isEmpty) {
    return <int>[];
  }

  int rows = tideHeights.length;
  int cols = tideHeights[0].length;

  List<List<int>> cost = List.generate(
    rows,
    (_) => List.filled(cols, 1 << 30),
  );
  List<List<int>> sum = List.generate(
    rows,
    (_) => List.filled(cols, 1 << 30),
  );
  List<List<int>> parent = List.generate(
    rows,
    (_) => List.filled(cols, -1),
  );

  for (int c = 0; c < cols; c++) {
    cost[0][c] = 0;
    sum[0][c] = tideHeights[0][c];
  }

  for (int r = 1; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      for (int pc = c - 1; pc <= c + 1; pc++) {
        if (pc < 0 || pc >= cols) {
          continue;
        }

        int nextCost = cost[r - 1][pc] +
            (tideHeights[r][c] - tideHeights[r - 1][pc]).abs();
        int nextSum = sum[r - 1][pc] + tideHeights[r][c];

        bool better = false;

        if (nextCost < cost[r][c]) {
          better = true;
        } else if (nextCost == cost[r][c]) {
          if (nextSum < sum[r][c]) {
            better = true;
          } else if (nextSum == sum[r][c] &&
              (parent[r][c] == -1 || pc < parent[r][c])) {
            better = true;
          }
        }

        if (better) {
          cost[r][c] = nextCost;
          sum[r][c] = nextSum;
          parent[r][c] = pc;
        }
      }
    }
  }

  int endCol = 0;
  for (int c = 1; c < cols; c++) {
    if (cost[rows - 1][c] < cost[rows - 1][endCol] ||
        (cost[rows - 1][c] == cost[rows - 1][endCol] &&
            (sum[rows - 1][c] < sum[rows - 1][endCol] ||
                (sum[rows - 1][c] == sum[rows - 1][endCol] &&
                    c < endCol)))) {
      endCol = c;
    }
  }

  List<int> path = List.filled(rows, 0);
  int current = endCol;

  for (int r = rows - 1; r >= 0; r--) {
    path[r] = current;
    current = parent[r][current];
  }

  return path;
}

@pragma('vm:entry-point')
void main() {
  assert(smoothestTideRoute([]).toString() == '[]');
  assert(smoothestTideRoute([[4, 2, 2]]).toString() == '[1]');
  assert(smoothestTideRoute([[5, 1, 5], [5, 100, 5], [5, 1, 5]]).toString() == '[0, 0, 0]');
  print('All tests passed!');
}

