Map<String, int> countBracketWins(List<String> players) {
  if (players.isEmpty) return {};
  if (players.length == 1) {
    return {players[0]: 0};
  }

  int mid = players.length ~/ 2;
  var left = countBracketWins(players.sublist(0, mid));
  var right = countBracketWins(players.sublist(mid));
  String winner = players[0];
  left[winner] = left[winner]! + 1;
  return {...left, ...right};
}

