@pragma('vm:entry-point')
bool validateDiceRoundLog(List<String> events) {
  List<List<int>> roundStack = [];

  for (final event in events) {
    if (event == 'START') {
      roundStack.add([]);
    } else if (event == 'END') {
      if (roundStack.isEmpty) {
        return false;
      }

      int total = 0;
      for (final roll in roundStack.last) {
        total += roll;
      }

      if (roundStack.last.length < 2 ||
          roundStack.last.length > 3 ||
          total < 3) {
        return false;
      }

      roundStack.removeLast();
    } else if (event == 'UNDO') {
      if (roundStack.isEmpty || roundStack.last.isEmpty) {
        return false;
      }

      roundStack.last.removeLast();
    } else if (event.startsWith('D:')) {
      if (roundStack.isEmpty) {
        return false;
      }

      int? value = int.tryParse(event.substring(2));
      if (value == null || value < 1 || value > 6) {
        return false;
      }

      roundStack.last.add(value);

      if (roundStack.last.length > 3) {
        return false;
      }
    } else {
      return false;
    }
  }

  return roundStack.isEmpty;
}

@pragma('vm:entry-point')
void main() {
  assert(validateDiceRoundLog(['START', 'D:4', 'D:2', 'END']) == true);
  assert(validateDiceRoundLog(['START', 'UNDO']) == false);
  assert(validateDiceRoundLog(['START', 'D:6', 'D:1', 'D:2', 'END']) == true);
  print('All tests passed!');
}

