  expect(candidate(['START', 'D:5', 'UNDO', 'D:2', 'D:2', 'END']), true);
  expect(candidate(['D:6']), false);
  expect(candidate(['START', 'D:1', 'END']), false);
  expect(candidate(['START', 'D:2', 'D:2', 'D:2', 'D:2']), false);
  expect(candidate(['START', 'D:6', 'D:1', 'D:1', 'END']), true);
  expect(candidate(['START', 'D:4', 'START', 'D:2', 'D:2', 'END', 'D:3', 'END']), true);
  expect(candidate(['START', 'D:4', 'START', 'D:2', 'END', 'END']), false);
}

