@pragma('vm:entry-point')
List<int> soilMoistureRowTotals(String gridLog) {
  if (gridLog.isEmpty) {
    return <int>[];
  }

  int moistureValue(String ch) {
    if (ch == 'D') return 1;
    if (ch == 'M') return 2;
    if (ch == 'W') return 3;
    return 0;
  }

  int scorePattern(String pattern) {
    int total = 0;
    int i = 0;

    while (i < pattern.length) {
      if (pattern[i] == '[') {
        int end = pattern.indexOf(']', i);
        if (end == -1) {
          end = pattern.length;
        }

        String inner = pattern.substring(i + 1, end);
        int innerSum = 0;
        int last = 0;

        for (int j = 0; j < inner.length; j++) {
          int v = moistureValue(inner[j]);
          if (v > 0) {
            innerSum += v;
            last = v;
          }
        }

        total += innerSum == 0 ? 0 : (innerSum * 2 - last);
        i = end + 1;
      } else {
        total += moistureValue(pattern[i]);
        i++;
      }
    }

    return total;
  }

  List<int> result = <int>[];
  List<String> rows = gridLog.split(';');

  for (String row in rows) {
    List<String> tokens = <String>[];
    String current = '';
    int depth = 0;

    for (int i = 0; i < row.length; i++) {
      String ch = row[i];
      if (ch == '[') depth++;
      if (ch == ']') depth--;

      if (ch == ',' && depth == 0) {
        tokens.add(current.trim());
        current = '';
      } else {
        current += ch;
      }
    }

    tokens.add(current.trim());

    int rowTotal = 0;

    for (String token in tokens) {
      if (token.isEmpty) continue;

      int repeat = 1;
      String body = token;
      int colon = token.indexOf(':');

      if (colon > 0) {
        String prefix = token.substring(0, colon);
        bool numeric = true;

        for (int i = 0; i < prefix.length; i++) {
          int c = prefix.codeUnitAt(i);
          if (c < 48 || c > 57) {
            numeric = false;
            break;
          }
        }

        if (numeric) {
          repeat = int.parse(prefix);
          body = token.substring(colon + 1);
        }
      }

      rowTotal += repeat * scorePattern(body);
    }

    result.add(rowTotal);
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(soilMoistureRowTotals("DM,W").toString() == "[6]");
  assert(soilMoistureRowTotals("2:[DW]").toString() == "[10]");
  assert(soilMoistureRowTotals("D,[MW,D];3:M").toString() == "[12, 6]");
  print('All tests passed!');
}

