@pragma('vm:entry-point')
bool validateTideRunChecksum(String report) {
  int split = report.indexOf('#');
  if (split <= 0 || split == report.length - 1) {
    return false;
  }

  String encoded = report.substring(0, split);
  String checksumText = report.substring(split + 1);

  int? expectedChecksum = int.tryParse(checksumText);
  if (expectedChecksum == null || expectedChecksum < 0) {
    return false;
  }

  int checksum = 0;
  int i = 0;

  while (i < encoded.length) {
    String level = encoded[i];
    if (level != 'H' && level != 'M' && level != 'L') {
      return false;
    }

    i++;
    if (i >= encoded.length || encoded.codeUnitAt(i) < 48 || encoded.codeUnitAt(i) > 57) {
      return false;
    }

    int start = i;
    while (i < encoded.length && encoded.codeUnitAt(i) >= 48 && encoded.codeUnitAt(i) <= 57) {
      i++;
    }

    int count = int.parse(encoded.substring(start, i));
    if (count <= 0) {
      return false;
    }

    if (level == 'H') {
      checksum += count * 5;
    } else if (level == 'M') {
      checksum += count * 3;
    } else {
      checksum += count;
    }
  }

  return checksum == expectedChecksum;
}

@pragma('vm:entry-point')
void main() {
  assert(validateTideRunChecksum('H2M1L3#16') == true);
  assert(validateTideRunChecksum('H1L2#8') == false);
  assert(validateTideRunChecksum('M4#12') == true);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = validateTideRunChecksum;

  expect(candidate('H2M1L3#16'), true);
  expect(candidate('M4#12'), true);
  expect(candidate('L5H1#10'), true);
  expect(candidate('H1L2#8'), false);
  expect(candidate('H0M1#3'), false);
  expect(candidate('X2L1#3'), false);
  expect(candidate('#0'), false);
  expect(candidate('H2M#13'), false);
}

