List<String> availableFrontRowSeats(String chart) {
  if (chart.isEmpty) {
    return [];
  }
  List<String> seats = [];
  for (String entry in chart.split(',')) {
    List<String> parts = entry.trim().split(':');
    if (parts.length == 2 &&
        parts[0].startsWith('A') &&
        parts[1] == 'open') {
      seats.add(parts[0]);
    }
  }
  return seats;
}

