@pragma('vm:entry-point')
List<String> batteryCycleStates(String log) {
  List<String> states = [];
  int charge = 0;

  for (int i = 0; i < log.length; i++) {
    String ch = log[i];
    if (ch == '+') {
      charge++;
    } else if (ch == '-' && charge > 0) {
      charge--;
    } else if (ch == '|') {
      if (charge == 0) {
        states.add('empty');
      } else if (charge >= 3) {
        states.add('full');
      } else {
        states.add('partial');
      }
      charge = 0;
    }
  }

  return states;
}

@pragma('vm:entry-point')
void main() {
  assert(batteryCycleStates("+++|").toString() == "[full]");
  assert(batteryCycleStates("+-|").toString() == "[empty]");
  assert(batteryCycleStates("++|+|").length == 2);
  print('All tests passed!');
}

tests:
