  final candidate = batteryCycleStates;

  expect(candidate("").toString(), "[]");
  expect(candidate("+").toString(), "[]");
  expect(candidate("+++|").toString(), "[full]");
  expect(candidate("++|").toString(), "[partial]");
  expect(candidate("+-|").toString(), "[empty]");
  expect(candidate("++|+|").toString(), "[partial, partial]");
  expect(candidate("--|").toString(), "[empty]");
  expect(candidate("++++|--|+++-|").toString(), "[full, empty, partial]");
}

